create table if not exists public.social_cuentas (id uuid primary key default gen_random_uuid(), sucursal_id uuid not null references public.sucursales(id), plataforma text not null check (plataforma in ('facebook','tiktok')), nombre text not null, username text, display_name text, zernio_account_id text not null unique, zernio_profile_id text, activo boolean not null default true, estado text not null default 'conectada' check (estado in ('conectada','requiere_reconexion','desconectada')), metadata jsonb, creado_en timestamptz not null default now(), actualizado_en timestamptz not null default now(), unique (sucursal_id, plataforma));
create table if not exists public.social_hilos (id uuid primary key default gen_random_uuid(), cuenta_id uuid not null references public.social_cuentas(id) on delete cascade, sucursal_id uuid not null references public.sucursales(id), zernio_conversation_id text not null, participant_id text, participant_username text, participant_name text, cliente_id uuid references public.clientes(id), ultimo_mensaje_at timestamptz, ultimo_mensaje_preview text, ultimo_inbound_at timestamptz, no_leidos_count integer not null default 0, estado text not null default 'abierto', asignado_tipo text, asignado_id uuid, creado_en timestamptz not null default now(), actualizado_en timestamptz not null default now(), unique (cuenta_id, zernio_conversation_id));
create table if not exists public.social_mensajes (id uuid primary key default gen_random_uuid(), hilo_id uuid not null references public.social_hilos(id) on delete cascade, direccion text not null check (direccion in ('in','out')), tipo_contenido text not null default 'text', cuerpo text, zernio_message_id text unique, estado text not null default 'enviado', error_detalle text, media_url text, responde_a_id uuid references public.social_mensajes(id), enviado_por_tipo text, enviado_por_id uuid, metadata jsonb, creado_en timestamptz not null default now());
create table if not exists public.social_webhook_eventos (id uuid primary key default gen_random_uuid(), zernio_event_id text not null unique, evento text not null, plataforma text, cuenta_zernio_id text, payload jsonb not null, procesado_en timestamptz not null default now());
create index if not exists social_hilos_sucursal_idx on public.social_hilos(sucursal_id); create index if not exists social_hilos_updated_idx on public.social_hilos(actualizado_en desc); create index if not exists social_mensajes_hilo_idx on public.social_mensajes(hilo_id, creado_en); create index if not exists social_webhook_cuenta_idx on public.social_webhook_eventos(cuenta_zernio_id);
alter table public.social_cuentas enable row level security; alter table public.social_hilos enable row level security; alter table public.social_mensajes enable row level security; alter table public.social_webhook_eventos enable row level security;
drop policy if exists "social_cuentas_select" on public.social_cuentas; drop policy if exists "social_cuentas_admin" on public.social_cuentas; drop policy if exists "social_hilos_scoped" on public.social_hilos; drop policy if exists "social_mensajes_scoped" on public.social_mensajes; drop policy if exists "social_webhook_admin" on public.social_webhook_eventos;
create policy "social_cuentas_select" on public.social_cuentas for select to authenticated using (public.app_is_admin() or sucursal_id = public.app_actor_sucursal_id()); create policy "social_cuentas_admin" on public.social_cuentas for all to authenticated using (public.app_is_admin()) with check (public.app_is_admin()); create policy "social_hilos_scoped" on public.social_hilos for all to authenticated using (public.app_is_admin() or sucursal_id = public.app_actor_sucursal_id()) with check (public.app_is_admin() or sucursal_id = public.app_actor_sucursal_id()); create policy "social_mensajes_scoped" on public.social_mensajes for all to authenticated using (public.app_is_admin() or exists (select 1 from public.social_hilos h where h.id = social_mensajes.hilo_id and h.sucursal_id = public.app_actor_sucursal_id())) with check (public.app_is_admin() or exists (select 1 from public.social_hilos h where h.id = social_mensajes.hilo_id and h.sucursal_id = public.app_actor_sucursal_id())); create policy "social_webhook_admin" on public.social_webhook_eventos for all to authenticated using (public.app_is_admin()) with check (public.app_is_admin());